#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using Cysharp.Threading.Tasks;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public class LanguagePackReaderDirectoryV0 : LanguagePackReaderV0, IResourcePackReaderDirectory
    {
        public LanguagePackReaderDirectoryV0(MainManager main) : base(main)
        {
        }

        public override async UniTask<ResourcePack?> ReadPack(string key, string path)
        {
            try
            {
                var packReadData = await UniTask.RunOnThreadPool(() => ReadPackData(key, path));
                if (packReadData == null)
                    return null;
                var pack = new ResourcePack(key);

                await UniTask.SwitchToMainThread();

                ApplyReadData(pack, packReadData, ReadTexture2D);

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包{path}失败：{e}");
                return null;
            }
        }
        private async UniTask<PackReadData> ReadPackData(string key, string path)
        {
            var packReadData = new PackReadData(key);
            var assetsDir = Path.Combine(path, "assets");
            foreach (var nspDir in Directory.EnumerateDirectories(assetsDir))
            {
                var nsp = Path.GetRelativePath(assetsDir, nspDir);
                foreach (var langDir in Directory.EnumerateDirectories(nspDir))
                {
                    var lang = Path.GetRelativePath(nspDir, langDir);
                    await ReadPackInLanguageFolder(nsp, lang, langDir, packReadData);
                }
            }
            return packReadData;
        }
        private async UniTask ReadPackInLanguageFolder(string nsp, string lang, string dir, PackReadData pack)
        {
            // 加载文本
            await ReadPackCatalogs(lang, dir, pack);

            // 加载贴图
            await ReadPackSprites(nsp, lang, dir, pack);
        }
        private async UniTask ReadPackCatalogs(string lang, string dir, PackReadData pack)
        {
            var catalogDictionary = new Dictionary<string, Catalog>();
            foreach (var moFile in Directory.EnumerateFiles(dir, "*.mo"))
            {
                var filenameWithoutExt = Path.GetFileNameWithoutExtension(moFile);
                var catalog = await LoadPackMOFileDirectory(moFile, lang);
                catalogDictionary.Add(filenameWithoutExt, catalog);
            }
            pack.catalogs.Add(lang, catalogDictionary);
        }
        private async UniTask<Catalog> LoadPackMOFileDirectory(string moFile, string lang)
        {
            using (var stream = File.Open(moFile, FileMode.Open))
            {
                using (MemoryStream memory = new MemoryStream())
                {
                    await stream.CopyToAsync(memory);
                    memory.Seek(0, SeekOrigin.Begin);
                    return new Catalog(memory, new CultureInfo(lang));
                }
            }
        }
        private async UniTask ReadPackSprites(string nsp, string lang, string dir, PackReadData pack)
        {
            var manifestPath = Path.Combine(dir, SPRITE_MANIFEST_FILENAME);
            if (File.Exists(manifestPath))
            {
                using var manifestStream = File.Open(manifestPath, FileMode.Open);
                using var manifestReader = new StreamReader(manifestStream);
                var manifestJson = await manifestReader.ReadToEndAsync();

                var manifest = JsonConvert.DeserializeObject<LocalizedSpriteManifest>(manifestJson);
                if (manifest == null)
                    return;
                ReadPackSpriteManifest(nsp, lang, dir, pack, manifest);
            }
        }
        private void ReadPackSpriteManifest(string nsp, string lang, string dir, PackReadData pack, LocalizedSpriteManifest manifest)
        {
            if (manifest.sprites != null)
            {
                foreach (var localizedSprite in manifest.sprites)
                {
                    if (string.IsNullOrEmpty(localizedSprite.texture))
                        continue;

                    var texturePath = Path.Combine(dir, "sprites", localizedSprite.texture).Replace("/", "\\");

                    if (!File.Exists(texturePath) || string.IsNullOrEmpty(localizedSprite.name))
                        continue;

                    var textureID = new NamespaceID(nsp, localizedSprite.texture);
                    var spriteID = new NamespaceID(nsp, localizedSprite.name);
                    var spriteRef = new SpriteReference(spriteID);
                    var spriteKey = new SpriteLookupKey(spriteRef, SpriteHelper.GetLanguageSpriteTag(lang));

                    var slice = new SliceData(spriteKey)
                    {
                        border = Vector4.zero,
                        extrude = 0,
                        meshType = SpriteMeshType.Tight,
                        pivot = new Vector2(localizedSprite.pivotX, localizedSprite.pivotY),
                        pixelsPerUnit = 100,
                        single = true,
                        spriteKey = spriteKey,
                    };
                    var spriteEntry = new SpriteEntry(textureID, texturePath, slice);
                    pack.spriteEntries.Add(spriteEntry);
                }
            }
            if (manifest.spritesheets != null)
            {
                foreach (var localizedSpritesheet in manifest.spritesheets)
                {
                    if (string.IsNullOrEmpty(localizedSpritesheet.texture))
                        continue;

                    var texturePath = Path.Combine(dir, "spritesheets", localizedSpritesheet.texture).Replace("/", "\\");

                    if (!File.Exists(texturePath) || string.IsNullOrEmpty(localizedSpritesheet.name))
                        continue;

                    var textureID = new NamespaceID(nsp, localizedSpritesheet.texture);
                    var resID = new NamespaceID(nsp, localizedSpritesheet.name);
                    var spritesheetEntry = new SpritesheetEntry(textureID, texturePath);
                    if (localizedSpritesheet.slices != null)
                    {
                        for (int i = 0; i < localizedSpritesheet.slices.Length; i++)
                        {
                            var slice = localizedSpritesheet.slices[i];
                            var spriteRef = new SpriteReference(resID, i);
                            var spriteKey = new SpriteLookupKey(spriteRef, SpriteHelper.GetLanguageSpriteTag(lang));

                            var sliceData = new SliceData(spriteKey)
                            {
                                border = Vector4.zero,
                                extrude = 0,
                                meshType = SpriteMeshType.Tight,
                                pivot = new Vector2(slice.pivotX, slice.pivotY),
                                pixelsPerUnit = 100,
                                rect = new Rect(slice.x, slice.y, slice.width, slice.height),
                                spriteKey = spriteKey
                            };
                            spritesheetEntry.slices.Add(sliceData);
                        }
                    }
                    pack.spritesheetEntries.Add(spritesheetEntry);
                }
            }
        }
        private Texture2D? ReadTexture2D(string texturePath, string name = "texture2D")
        {
            if (!File.Exists(texturePath))
                return null;

            using var spriteStream = File.Open(texturePath, FileMode.Open);
            using var spriteMemory = new MemoryStream();
            spriteStream.CopyTo(spriteMemory);

            var bytes = spriteMemory.ToArray();
            return Main.ResourceManager.GenerateTextureFromBytes(bytes, name);
        }
    }
}
